// /intake-register — generated by `pnpm gen:screen intake-register`. E2 AC6, SOP-DEL-01 §12: every submission —
// Project ID, submitted, decision, decided, returns, working days to acceptance — with a month filter for the
// monthly review with the Sales Lead and a CSV export of what is shown. Director, sponsor and management only.
import { useEffect, useState } from 'react';
import { Button, Card, FormMessage, PageHeader, TextField, useI18n } from '@ocs/ui';
import { loadIntakeRegister, type IntakeRegisterRow } from '../api.ts';

const COLUMNS = [
  'projectId',
  'version',
  'submittedOn',
  'decision',
  'decidedOn',
  'returns',
  'daysToAcceptance',
] as const;

/** RFC 4180: quote every field, double the quotes. */
const csvOf = (rows: readonly IntakeRegisterRow[]) =>
  [COLUMNS, ...rows.map((r) => COLUMNS.map((c) => String(r[c] ?? '')))]
    .map((line) => line.map((v) => `"${v.replace(/"/g, '""')}"`).join(','))
    .join('\r\n');

export function IntakeRegisterPage() {
  const { t } = useI18n();
  const [month, setMonth] = useState('');
  const [rows, setRows] = useState<IntakeRegisterRow[] | 'forbidden' | 'failed' | null>(null);
  useEffect(() => {
    loadIntakeRegister(month).then(
      (r) => {
        setRows(r ?? 'forbidden');
      },
      () => {
        setRows('failed');
      },
    );
  }, [month]);
  const exportCsv = (list: readonly IntakeRegisterRow[]) => {
    const url = URL.createObjectURL(new Blob([csvOf(list)], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `intake-register${month ? `-${month}` : ''}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <>
      <PageHeader eyebrow={`/ ${t('intakeRegister.title')}`} title={t('intakeRegister.title')} />
      <Card>
        {rows === null ? <p>{t('common.loading')}</p> : null}
        {rows === 'forbidden' ? <p>{t('intakeRegister.noAccess')}</p> : null}
        {rows === 'failed' ? <FormMessage tone="error">{t('intakeRegister.failed')}</FormMessage> : null}
        {Array.isArray(rows) ? (
          <div className="ocs-stack">
            <TextField
              id="register-month"
              label={t('intakeRegister.month')}
              type="month"
              value={month}
              onChange={(e) => {
                setMonth(e.currentTarget.value);
              }}
            />
            {rows.length === 0 ? (
              <p>{t('intakeRegister.none')}</p>
            ) : (
              <table className="ocs-table">
                <thead>
                  <tr>
                    {COLUMNS.map((c) => (
                      <th key={c} scope="col">
                        {t(`intakeRegister.col.${c}`)}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {rows.map((r) => (
                    <tr key={`${r.projectId}-${String(r.version)}`}>
                      <td>{r.projectId}</td>
                      <td>{r.version}</td>
                      <td>{r.submittedOn}</td>
                      <td>{t(`intakeRegister.decision.${r.decision}`)}</td>
                      <td>{r.decidedOn ?? '—'}</td>
                      <td>{r.returns}</td>
                      <td>{r.daysToAcceptance ?? '—'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
            <div>
              <Button
                type="button"
                onClick={() => {
                  exportCsv(rows);
                }}
              >
                {t('intakeRegister.export')}
              </Button>
            </div>
          </div>
        ) : null}
      </Card>
    </>
  );
}
